insert into public.occupation_requirements(occupation_id,country_code,kind,mandatory,detail,source_id,as_of)
select c.occupation_id,'US','experience',false,v.detail,(select id from src),'2026-11-27' from v join public.occupation_codes c on c.country_code='US' and c.code=v.soc;
